
-- Handbook v1.14 remediation: every database row now carries a distinct study, budget, or care fact.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'translated record' WHEN 2 THEN 'translated record' WHEN 3 THEN 'translated record'
      WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record' WHEN 6 THEN 'translated recordpurchasetranslated record' WHEN 7 THEN 'stationerystocktranslated record'
      WHEN 8 THEN 'follow-up appointmenttranslated recordbudget' WHEN 9 THEN 'rehabilitationtranslated record' WHEN 10 THEN 'translated recordsteps' WHEN 11 THEN 'translated recordpaintranslated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated record' WHEN 15 THEN 'translated record'
      ELSE 'translated record' END AS record_topic,
    CASE rowid % 19
      WHEN 0 THEN 'completed' WHEN 1 THEN 'in progress' WHEN 2 THEN 'awaiting review' WHEN 3 THEN 'source needed'
      WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record' WHEN 6 THEN 'translated recordbudget' WHEN 7 THEN 'translated record'
      WHEN 8 THEN 'translated record' WHEN 9 THEN 'translated record' WHEN 10 THEN 'translated record' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated recordfollow-up appointmenttranslated record' WHEN 14 THEN 'translated recordemail' WHEN 15 THEN 'translated record'
      WHEN 16 THEN 'translated record' WHEN 17 THEN 'translated record' ELSE 'translated record' END AS record_status
  FROM database_rows WHERE row_id LIKE 'row_noise_%'
)
UPDATE database_rows
SET properties_json=json_object(
      'name',(SELECT record_topic FROM facts WHERE facts.rid=database_rows.rowid),
      'status',(SELECT record_status FROM facts WHERE facts.rid=database_rows.rowid),
      'record_kind',CASE database_id WHEN 'db_exam_progress' THEN 'study_progress' WHEN 'db_budget' THEN 'budget_entry' ELSE 'care_observation' END,
      'actionable',CASE rowid % 4 WHEN 0 THEN 1 ELSE 0 END,
      'source_stage','seed'
    ),
    row_id=replace(row_id,'row_noise_','row_context_')
WHERE row_id LIKE 'row_noise_%';
